<script setup lang="ts">
import { computed, ref } from "vue";
import { Mountain, LayoutDashboard, Radio, Camera, Bell, Database, Settings2, CircleHelp, ChevronDown, RefreshCw, Box, Pause, Play, SkipForward, RotateCcw, ShieldCheck, TriangleAlert, X, Check, Cable, ExternalLink, Activity } from "lucide-vue-next";
import TerrainScene from "./components/TerrainScene.vue";
import ConnectorPanel from "./platform/ConnectorPanel.vue";
import VisionPanel from "./platform/VisionPanel.vue";
import TinyQuakePanel from "./platform/TinyQuakePanel.vue";
import PlatformTrend from "./platform/PlatformTrend.vue";
import { usePlatform } from "./platform/usePlatform";
import { connectionSettings, errorMessage, saveConnection } from "./platform/api";
import { dateTime, deviceKey, levelColors, levelNames, reading, sensorFields, type TelemetryRow, normalizeLevel } from "./platform/types";
import "./styles/platform.css";
const emit = defineEmits<{ localDemo: [] }>();
const { dashboard, health, devices, selectedKey, selected, history, historyCursor, historyLoading, moreHistory, connection, error, actionError, updatedAt, busy, reconnect, select, action } = usePlatform();
const page = ref("overview");
const settings = ref<HTMLDialogElement>();
const resetConfirmation = ref<HTMLDialogElement>();
const guide = ref<HTMLDialogElement>();
const apiBase = ref(connectionSettings.base);
const apiToken = ref(connectionSettings.token);
const settingsError = ref("");
const historyExpanded = ref<string | null>(null);
const latest = computed(() => dashboard.value?.latest);
const fresh = computed(() => connection.value === "online" && !!latest.value && !latest.value.stale);
const risk = computed(() => fresh.value ? latest.value?.risk : null);
const level = computed(() => risk.value?.level || "unknown");
const color = computed(() => levelColors[level.value]);
const riskReason = computed(() => connection.value === "offline" ? "后端连接已断开，当前读数已清空。" : latest.value?.stale ? "数据已过期，等待设备发送新的有效采样。" : risk.value?.reason || "等待有效遥测；未标定数据不输出风险分数。");
const isDemo = computed(() => selected.value?.site_id === "DEMO" && selected.value?.device_id === "DEMO-NODE-01" && selected.value?.source === "MOCK");
const sourceName = computed(() => selected.value?.source === "REAL" ? "真实接入" : selected.value?.source === "MOCK" ? isDemo.value ? "后端演示" : "模拟接入" : "尚未选择来源");
const elapsed = computed(() => dashboard.value?.demo?.elapsed_seconds || 0);
const sensors = computed(() => ({ moisture: fresh.value ? latest.value?.sensors.moisture ?? null : null, tilt: fresh.value ? latest.value?.sensors.tilt ?? null : null, vibration: fresh.value ? latest.value?.sensors.vibration ?? null : null, rain: fresh.value ? latest.value?.sensors.rain ?? null : null, crack: fresh.value ? latest.value?.sensors.crack ?? null : null }));
const nav = [{ id: "overview", label: "监测总览", icon: LayoutDashboard }, { id: "tinyquake", label: "TinyQuake 实验", icon: Activity }, { id: "vision", label: "视觉证据", icon: Camera }, { id: "alarms", label: "告警与事件", icon: Bell }, { id: "history", label: "历史数据", icon: Database }, { id: "connectors", label: "配置与接入", icon: Cable }];
const pageName = computed(() => nav.find((x) => x.id === page.value)?.label || "监测总览");
const alarms = computed(() => dashboard.value?.alarms || []);
const unacknowledged = computed(() => alarms.value.filter((x) => !x.acknowledged).length);
const scenarios = [{ id: "A", label: "稳定监测" }, { id: "B", label: "持续暴雨" }, { id: "C", label: "位移异常" }, { id: "D", label: "极端灾害" }];
const systemFields = [{ key: "edge_online", name: "边缘节点" }, { key: "wifi_up", name: "Wi-Fi" }, { key: "mqtt_up", name: "MQTT 上报" }, { key: "lora_ready", name: "LoRa 就绪" }, { key: "sd_ok", name: "本地存储" }];
function openSettings() { apiBase.value = connectionSettings.base; apiToken.value = connectionSettings.token; settingsError.value = ""; settings.value?.showModal(); }
function applySettings() {
  try { saveConnection(apiBase.value, apiToken.value); settings.value?.close(); }
  catch (cause) { settingsError.value = errorMessage(cause); }
}
function navigate(id: string) { page.value = id; window.scrollTo({ top: 0, behavior: "instant" }); }
function confirmReset() {
  if (!isDemo.value || busy.value) return;
  resetConfirmation.value?.close();
  void action("/demo/reset");
}
function inspect(row: TelemetryRow) { historyExpanded.value = historyExpanded.value === row.id ? null : row.id; }
const numberCount = (value: number | undefined) => value == null ? "—" : value.toLocaleString("zh-CN");
function stateLabel(key: string) { const value = fresh.value ? latest.value?.system?.[key] : null; return value == null ? "未知" : value ? "就绪" : "未就绪"; }
</script>
<template>
  <div class="app-shell platform-shell" :style="{ '--risk-color': color }">
    <aside class="sidebar"><a class="brand-mark" href="#" aria-label="智哨防灾平台首页" @click.prevent="navigate('overview')"><Mountain :size="27" :stroke-width="1.6" /></a><div class="sidebar-rule" /><nav aria-label="平台导航"><button v-for="item in nav" :key="item.id" :class="['nav-button', { active: page === item.id }]" :aria-label="item.label" :title="item.label" @click="navigate(item.id)"><component :is="item.icon" :size="21" /><span class="nav-tooltip">{{ item.label }}</span><i v-if="item.id === 'alarms' && unacknowledged" class="nav-alert" /></button></nav><div class="sidebar-bottom"><button class="nav-button" aria-label="平台使用说明" @click="guide?.showModal()"><CircleHelp :size="20" /></button><button class="nav-button" aria-label="后端连接设置" @click="openSettings"><Settings2 :size="20" /></button><span class="avatar" title="智哨工作空间">ZM</span></div></aside>
    <div class="workspace"><header class="topbar"><div class="workspace-brand">智哨防灾<span>/</span><span class="breadcrumb">多模态监测平台</span><ChevronDown :size="13" /></div><div class="topbar-right"><span :class="['connection-pill', { online: connection === 'online', offline: connection === 'offline' }]" data-testid="backend-status"><i class="status-dot" />{{ connection === 'online' ? '后端已连接' : connection === 'offline' ? '后端失联' : '连接中…' }}</span><button class="icon-button" aria-label="刷新后端数据" title="刷新后端数据" @click="reconnect"><RefreshCw :size="16" /></button><button class="secondary-button settings-trigger" @click="openSettings"><Settings2 :size="14" />连接设置</button></div></header>
      <main>
        <div class="page-heading"><div><h1>{{ pageName }}<span>多模态指挥中心</span></h1><p>{{ page === 'overview' ? '传感器与视觉证据汇入同一工作空间，变化可追溯。' : page === 'tinyquake' ? '核查 ESP32 模型输出，参考波形与实采数据分开展示。' : page === 'connectors' ? '配置数据入口，逐步接入网关、Atlas 与现场设备。' : page === 'vision' ? '把图像变化变成可核查、可回放的视觉证据。' : page === 'history' ? '查看持久化原始遥测，核查每一次入库记录。' : '核查风险来源，确认处理状态与系统事件。' }}</p></div><div v-if="page !== 'tinyquake'" class="platform-device-selector"><label for="platform-device">站点 / 设备 / 来源</label><select id="platform-device" :value="selectedKey" @change="select(($event.target as HTMLSelectElement).value)" aria-label="选择设备与数据来源"><option v-if="!devices.length" value="">等待设备接入</option><option v-for="device in devices" :key="deviceKey(device)" :value="deviceKey(device)">{{ device.site_id }} / {{ device.device_id }} / {{ device.source }}</option></select></div></div>
        <div v-if="connection === 'offline'" class="backend-alert" role="alert"><TriangleAlert :size="20" /><div><strong>无法连接后端，实时读数已清空</strong><p>{{ error }}。请确认服务已启动；需要认证时在连接设置中填写访问密钥。</p></div><button class="secondary-button" @click="openSettings">检查连接</button></div>
        <div v-else-if="connection === 'loading'" class="backend-alert neutral" role="status"><RefreshCw :size="18" /><div><strong>正在读取后端</strong><p>平台不会自动切换为本地模拟数据。</p></div></div>
        <div v-if="page !== 'tinyquake'" class="platform-context"><div><span :class="['source-badge', selected?.source?.toLowerCase()]">{{ selected?.source || '—' }}</span><strong>{{ sourceName }}</strong><span>{{ selected?.scope || '未选择设备' }}</span><span v-if="latest?.stale" class="stale-tag">数据已过期 · {{ Math.floor(latest.age_seconds) }} 秒数据年龄</span><span v-else-if="latest && fresh">最新入库 {{ dateTime(latest.received_at) }}</span><span v-else>等待有效数据</span></div><span><Database :size="12" />{{ health?.storage?.durable ? 'SQLite 持久化' : '存储状态未知' }}<span class="context-update"> · 读取 {{ dateTime(updatedAt) }}</span></span></div>
        <p v-if="actionError" class="inline-error" role="alert">{{ actionError }}</p>
        <template v-if="page === 'overview'">
          <div v-if="isDemo" class="simulation-bar platform-demo-bar"><div class="simulation-status"><Radio :size="15" /><strong>后端演示</strong><span>{{ dashboard?.demo?.running ? '运行中' : '已暂停' }} · {{ elapsed }} 秒</span><span class="demo-storage-note">样本写入数据库</span></div><div class="platform-scenarios"><button v-for="scenario in scenarios" :key="scenario.id" :class="{ selected: dashboard?.demo?.scenario === scenario.id }" :disabled="busy || connection !== 'online'" @click="action('/demo/scenario', { scenario: scenario.id })">{{ scenario.label }}</button></div><div class="playback-controls"><button class="playback-button" :disabled="busy || connection !== 'online'" :aria-label="dashboard?.demo?.running ? '暂停后端演示' : '继续后端演示'" @click="action('/demo/control', { running: !dashboard?.demo?.running })"><Pause v-if="dashboard?.demo?.running" :size="14" /><Play v-else :size="14" />{{ dashboard?.demo?.running ? '暂停' : '继续' }}</button><button class="icon-button" aria-label="后端演示推进一步" :disabled="busy || connection !== 'online'" @click="action('/demo/step')"><SkipForward :size="16" /></button><button class="icon-button" aria-label="重置后端演示" :disabled="busy || connection !== 'online'" @click="resetConfirmation?.showModal()"><RotateCcw :size="15" /></button></div></div>
          <div v-if="level === 'high' || level === 'critical'" class="risk-notice" role="status"><TriangleAlert :size="17" /><strong>{{ levelNames[level] }}</strong><span>{{ riskReason }}</span><button @click="navigate('alarms')">查看告警<ExternalLink :size="14" /></button></div>
          <div class="hero-grid platform-hero"><section class="panel terrain-panel"><div class="terrain-heading"><div><Box :size="17" /><h2>边坡数字孪生</h2><span class="mini-badge">示意地形</span></div><span class="terrain-online"><i :class="['status-dot', { paused: !fresh }]" />{{ fresh ? '后端遥测驱动' : '等待有效遥测' }}</span></div><div class="terrain-viewport"><TerrainScene :score="risk?.final_score ?? 0" :unknown="risk?.final_score == null" :sensors="sensors" :running="fresh && isDemo && !!dashboard?.demo?.running" :elapsed="elapsed" :gateway-online="fresh ? latest?.system.edge_online ?? undefined : undefined" :platform="true" :device-label="selected?.device_id || '未选择设备'" :reset-key="selectedKey" /></div><div class="terrain-disclosure"><Mountain :size="12" />程序化示意地形，非现场 DEM；风险、雨量与湿度来自所选后端数据流。</div></section>
            <section class="panel risk-panel platform-risk"><div class="risk-heading"><h2>风险评估</h2><span class="source-badge">{{ isDemo ? '演示算法' : risk?.mode === 'fused' ? '多模态融合' : '传感器通道' }}</span></div><div class="risk-overview"><div class="risk-number" data-testid="platform-risk-score">{{ risk?.final_score == null ? '—' : Math.floor(risk.final_score) }}<span>/ 100</span></div><div :class="['risk-state-symbol', { unknown: level === 'unknown' }]" :style="{ color, borderColor: color + '22' }"><ShieldCheck v-if="level === 'low'" :size="27" /><TriangleAlert v-else-if="level !== 'unknown'" :size="27" /><Activity v-else :size="27" /></div></div><div class="risk-level"><span :style="{ color, background: color + '12' }"><i />{{ latest?.stale ? '数据已过期' : levelNames[level] }}</span><small>{{ isDemo ? '演示评分，非灾害预测' : '设备上报，标定状态未核验' }}</small></div><p class="risk-description platform-risk-reason">{{ riskReason }}</p><div class="risk-channels"><div><span>传感器</span><strong>{{ reading(risk?.sensor_score) }}</strong></div><div><span>视觉</span><strong>{{ reading(risk?.vision_score) }}</strong><small v-if="risk?.vision_score == null">未标定</small></div><div><span>最终</span><strong>{{ reading(risk?.final_score) }}</strong></div></div><div class="trend-header"><span>后端风险历史</span><span>{{ dashboard?.history?.length || 0 }} 个样本</span></div><PlatformTrend :points="dashboard?.history || []" :color="color" /><div class="risk-footnote"><ShieldCheck :size="12" />缺测、过期与未标定均显示为空值</div></section>
          </div>
          <div class="section-label"><h2>传感器遥测</h2><span>{{ sourceName }} · 采集 {{ dateTime(latest?.source_time) }}</span></div>
          <section class="sensor-grid platform-sensors" aria-label="后端传感器读数"><article v-for="field in sensorFields" :key="field.key" class="panel platform-sensor"><div><span>{{ field.label }}</span><i :class="['status-dot', { paused: sensors[field.key] == null }]" /></div><div class="platform-sensor-reading" :data-testid="`reading-${field.key}`">{{ reading(sensors[field.key], field.decimals) }}<span>{{ field.unit }}</span></div><small>{{ sensors[field.key] == null ? latest?.stale ? '采样已过期' : '暂无有效读数' : selected?.source === 'MOCK' ? '后端模拟数据' : '设备上报数据' }}</small></article></section>
          <div class="platform-operations"><section class="panel platform-section"><div class="platform-panel-heading"><div><Radio :size="18" /><div><h2>设备链路状态</h2><p>由上报消息中的系统状态提供。</p></div></div></div><div class="device-health-grid"><div v-for="field in systemFields" :key="field.key"><i :class="['status-dot', { paused: !fresh || !latest?.system?.[field.key] }]" /><span>{{ field.name }}</span><strong>{{ stateLabel(field.key) }}</strong></div></div><p class="system-note">{{ fresh && latest?.system.sensor_degraded ? '设备报告传感器降级，请检查原始遥测。' : '链路就绪状态以设备上报为准；不表示平台主动完成了端到端探测。' }}</p></section><section class="panel platform-section"><div class="platform-panel-heading"><div><Database :size="18" /><div><h2>当前数据流</h2><p>{{ selected?.site_id || '—' }} / {{ selected?.device_id || '—' }}</p></div></div><button class="text-button" @click="navigate('history')">查看历史</button></div><div class="platform-counts"><div><strong>{{ numberCount(dashboard?.stats.telemetry_count) }}</strong><span>遥测记录</span></div><div><strong>{{ numberCount(dashboard?.stats.alarm_count) }}</strong><span>告警记录</span></div><div><strong>{{ numberCount(dashboard?.stats.evidence_count) }}</strong><span>视觉证据</span></div></div></section></div>
          <section class="panel platform-section"><div class="platform-panel-heading"><div><Camera :size="18" /><div><h2>视觉证据通道</h2><p>变化检测基线已就绪，支持图像上传、参考对比和 ROI。</p></div></div><button class="secondary-button" @click="navigate('vision')">上传与分析</button></div><div class="vision-intro"><span><i class="status-dot paused" />视觉风险尚未标定</span><p>{{ dashboard?.vision?.latest_result ? '已保存分析结果，可进入视觉证据查看图像变化和质量。' : '上传图像建立视觉证据，OpenCV 指标暂不参与风险融合。' }}</p><strong>{{ numberCount(dashboard?.stats.evidence_count) }} <small>份证据</small></strong></div></section>
        </template>
        <ConnectorPanel v-else-if="page === 'connectors'" :connectors="dashboard?.connectors || []" :statuses="health?.mqtt || []" :connected="connection === 'online'" @refresh="reconnect" />
        <TinyQuakePanel v-else-if="page === 'tinyquake'" :connected="connection === 'online'" :revision="updatedAt" />
        <VisionPanel v-else-if="page === 'vision'" :device="selected" :connected="connection === 'online'" :revision="updatedAt" @refresh="reconnect" />
        <template v-else-if="page === 'alarms'">
          <section class="panel platform-section"><div class="platform-panel-heading"><div><Bell :size="19" /><div><h2>风险告警</h2><p>人工确认会保存到数据库，刷新或重启后保留。</p></div></div><span class="source-badge">{{ unacknowledged }} 条待确认</span></div><div v-if="!alarms.length" class="platform-empty"><ShieldCheck :size="30" /><h3>{{ connection === 'online' ? '当前数据流暂无告警' : '告警数据不可用' }}</h3><p>{{ connection === 'online' ? '切换设备或等待已标定通道触发风险条件。' : '恢复后端连接后读取已保存的告警。' }}</p></div><div v-for="alarm in alarms" :key="alarm.id" class="platform-alarm"><div class="alarm-severity" :style="{ background: levelColors[normalizeLevel(alarm.level)] + '14', color: levelColors[normalizeLevel(alarm.level)] }"><TriangleAlert :size="19" /></div><div><strong :style="{ color: levelColors[normalizeLevel(alarm.level)] }">{{ levelNames[normalizeLevel(alarm.level)] }} · {{ reading(alarm.score) }}</strong><p>{{ alarm.reason }}</p><small>{{ dateTime(alarm.created_at) }} · {{ selected?.source }}</small></div><span v-if="alarm.acknowledged" class="acknowledged"><Check :size="14" />已确认</span><button v-else class="secondary-button" :disabled="busy" @click="action(`/alarms/${encodeURIComponent(alarm.id)}/ack`)"><Check :size="14" />确认告警</button></div></section>
          <section class="panel platform-section"><div class="platform-panel-heading"><div><Activity :size="18" /><div><h2>事件记录</h2><p>接入、演示控制与风险变化。</p></div></div></div><div v-if="!dashboard?.events?.length" class="platform-empty compact-empty">暂无事件</div><div v-for="event in dashboard?.events || []" :key="event.id" class="platform-event"><time>{{ dateTime(event.created_at) }}</time><span class="source-badge">{{ event.kind }}</span><p>{{ event.message }}</p></div></section>
        </template>
        <section v-else-if="page === 'history'" class="panel platform-section history-panel"><div class="platform-panel-heading"><div><Database :size="19" /><div><h2>遥测入库记录</h2><p>已加载 {{ history.length }} 条 · {{ selected?.site_id || '—' }} / {{ selected?.device_id || '—' }} / {{ selected?.source || '—' }}</p></div></div><button class="secondary-button" @click="reconnect"><RefreshCw :size="14" />刷新历史</button></div><div v-if="!history.length" class="platform-empty"><Database :size="30" /><h3>暂无遥测记录</h3><p>有效消息接入后，原始数据会保存到数据库。</p></div><div v-else class="platform-table-scroll"><table class="platform-table"><thead><tr><th>入库时间</th><th>数据来源</th><th>记录 ID</th><th>原始消息</th></tr></thead><tbody><template v-for="row in history" :key="row.id"><tr><td>{{ dateTime(row.received_at) }}</td><td><span :class="['source-badge', String(row.source || selected?.source).toLowerCase()]">{{ row.source || selected?.source }}</span></td><td><code>{{ row.id }}</code></td><td><button class="text-button" @click="inspect(row)">{{ historyExpanded === row.id ? '收起' : '查看 JSON' }}</button></td></tr><tr v-if="historyExpanded === row.id"><td colspan="4"><pre class="payload-view">{{ JSON.stringify(row.payload || row, null, 2) }}</pre></td></tr></template></tbody></table><div v-if="historyCursor" class="history-more"><button class="secondary-button" :disabled="historyLoading" @click="moreHistory">{{ historyLoading ? '读取中…' : '加载更早记录' }}</button></div></div></section>
        <footer class="page-footer platform-footer"><div><Mountain :size="15" /><span>智哨防灾</span><span>感知 · 分析 · 预警</span></div><button class="text-button" @click="emit('localDemo')">进入独立本地演示<ExternalLink :size="12" /></button></footer>
      </main><div class="bottom-status"><span><i :class="['status-dot', { paused: connection !== 'online' }]" />{{ connection === 'online' ? '平台在线' : '后端待连接' }}</span><span v-if="page === 'tinyquake'">TinyQuake · 独立数据流 · TEST_ONLY</span><span v-else>{{ selected?.site_id || '—' }} / {{ selected?.device_id || '—' }} / {{ selected?.source || '—' }}</span><span>{{ page === 'tinyquake' ? '实验输出不参与风险评分' : '缺测不补零 · 视觉基线未标定' }}</span></div>
    </div>
    <dialog ref="resetConfirmation" class="modal native-modal platform-modal" aria-labelledby="reset-demo-title" aria-describedby="reset-demo-description"><h2 id="reset-demo-title">重置后端演示？</h2><p id="reset-demo-description">这会清空 DEMO / DEMO-NODE-01 的模拟遥测、告警与事件记录，并恢复正常场景。其它设备的数据会保留。</p><div class="form-actions"><button class="secondary-button" autofocus @click="resetConfirmation?.close()">取消</button><button class="primary-button compact" :disabled="busy" @click="confirmReset">重置演示</button></div></dialog>
    <dialog ref="settings" class="modal native-modal platform-modal" aria-labelledby="connection-settings-title"><button class="modal-close icon-button" aria-label="关闭连接设置" @click="settings?.close()"><X :size="18" /></button><h2 id="connection-settings-title">后端连接设置</h2><p>默认连接同源后端。开发环境会将 /api 转发至本机 8000 端口。</p><form @submit.prevent="applySettings"><label>API 地址<input v-model="apiBase" required placeholder="/api/v1" autocomplete="off" /></label><label>访问密钥（可选）<input v-model="apiToken" type="password" autocomplete="off" placeholder="与后端配置的 API 密钥保持一致" /></label><p class="connection-note">密钥仅保存在当前浏览器会话，通过 Authorization 请求头发送。关闭此会话后清除。</p><p v-if="settingsError" class="inline-error" role="alert">{{ settingsError }}</p><button class="primary-button" type="submit">保存并连接</button></form></dialog>
    <dialog ref="guide" class="modal native-modal platform-modal" aria-labelledby="platform-guide-title"><button class="modal-close icon-button" aria-label="关闭平台说明" @click="guide?.close()"><X :size="18" /></button><span class="modal-brand"><Mountain :size="25" /></span><h2 id="platform-guide-title">从数据接入，到证据核查。</h2><p>平台默认读取 FastAPI 后端，遥测、配置、图像和告警存入数据库。设备选择器按站点、设备和 MOCK / REAL 来源区分数据流。</p><div class="guide-steps"><div><span>01</span><p><strong>先验证流程</strong>后端演示生成明确标记为 MOCK 的样本，支持场景、暂停和单步。</p></div><div><span>02</span><p><strong>接入真实设备</strong>配置 MQTT 连接器，按仓库 v2 协议接收遥测。</p></div><div><span>03</span><p><strong>关联视觉证据</strong>上传图像，比较同相机前后变化，保留质量指标与叠加图。</p></div></div><p class="disclosure">真实遥测在正式标定配置交付前可能没有风险分数；图像指标尚未标定为灾害概率。三维场景为示意地形。后端失联时不会自动以模拟数据替代。</p><button class="primary-button" @click="guide?.close()">了解</button></dialog>
  </div>
</template>
